bmql-safe.syntax:
${1:records} = bmql("SELECT ${2:column} FROM ${3:table} WHERE ${4:column} = $${5:param}", ${5:param});
if (not(isnull(${1:records})) AND sizeofarray(${1:records}) > 0) {
	for ${6:row} in ${1:records} {
		${7:val} = get(${6:row}, "${2:column}");
		${0}
	}
}

